using System;
using System.Linq;
using System.IO;
using System.Text;
using System.Runtime.Serialization.Json;
using System.Drawing;
using System.Windows.Forms;

namespace Ara {
 public static class DiagnosticTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static DiagnosticEntry[] Entries(){return File.ReadAllLines(Diagnostics.CurrentFile).Where(x=>x.Length>0).Select(x=>{using(var m=new MemoryStream(Encoding.UTF8.GetBytes(x)))return (DiagnosticEntry)new DataContractJsonSerializer(typeof(DiagnosticEntry)).ReadObject(m);}).ToArray();}
  static void ThrowForLog(){throw new ObjectDisposedException("ContextMenuStrip","한글 오류 기록 테스트");}
  public static void Run(Action<string,Action> check,string dir){
   check("logging: errors preserve exception stack, recent actions and session context",()=>{Diagnostics.Initialize(Path.Combine(dir,"logger-error","state.json"));Diagnostics.Context=()=>"date=2026-10-14; wake=15:00; selection=1:90-95";Diagnostics.Recover=null;Diagnostics.Action("score","3");Diagnostics.Action("menu-open");try{ThrowForLog();}catch(Exception e){Diagnostics.Error("test-error",e);}var entries=Entries();var error=entries.Last();Assert(error.level=="ERROR"&&error.exception.Contains("ContextMenuStrip")&&error.exception.Contains("ThrowForLog")&&error.exception.Contains("한글 오류"),"exception and stack");Assert(error.details.Contains("score 3")&&error.details.Contains("menu-open")&&error.context.Contains("90-95")&&entries.All(x=>x.session==error.session)&&!string.IsNullOrEmpty(error.time),"action/context/session");});
   check("logging: UI exception path logs and attempts recovery without nested dialog",()=>{bool recovered=false;Diagnostics.Recover=()=>{recovered=true;return true;};Diagnostics.ReportUiError(new InvalidOperationException("UI hook test"),false);Assert(recovered&&Entries().Last().action=="unhandled-ui","global handler path");Diagnostics.Recover=null;});
   check("logging: trace excludes memo, task text and linked URLs",()=>{Diagnostics.Initialize(Path.Combine(dir,"logger-form","state.json"));var s=State.New();s.GetDay(DateTime.Today).Note="PRIVATE-MEMO-SENTINEL";s.WorkLink="https://private.invalid/?token=PRIVATE-URL-SENTINEL";s.Tasks.Add(new Todo{Id="private",Text="PRIVATE-TASK-SENTINEL",Group="작업"});using(var f=new MainForm(new Store(Path.Combine(dir,"logger-form","state.json")),s,true)){f.Show();Application.DoEvents();f.Board.SetSelection(new CellSelection{Lane=1,First=90,Last=95});f.ApplyQuickScore(3);string text=File.ReadAllText(Diagnostics.CurrentFile);Assert(text.Contains("selection=1:90-95")&&text.Contains("ApplyQuickScore")&&!text.Contains("PRIVATE-MEMO")&&!text.Contains("PRIVATE-URL")&&!text.Contains("PRIVATE-TASK"),"minimal diagnostics");f.Quit();}});
   check("logging: files rotate at 2MB and retain only 14 trace files",()=>{Diagnostics.Initialize(Path.Combine(dir,"logger-rotate","state.json"));Diagnostics.Context=null;Diagnostics.Recover=null;string original=Diagnostics.CurrentFile;using(var stream=new FileStream(original,FileMode.Open,FileAccess.Write)){stream.SetLength(2*1024*1024);}Diagnostics.Action("rotate-test");Assert(Diagnostics.CurrentFile!=original&&File.Exists(original)&&Entries().Last().action=="rotate-test","rotation");string state=Path.Combine(dir,"logger-rotate","state.json");File.WriteAllText(state,"preserve me");for(int i=0;i<20;i++){string file=Path.Combine(Diagnostics.DirectoryPath,"ara-2000-01-01-"+i.ToString("000")+".jsonl");File.WriteAllText(file,"old");File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddDays(-20).AddMinutes(i));}Diagnostics.Action("retention-test");Assert(Directory.GetFiles(Diagnostics.DirectoryPath,"ara-*.jsonl").Length==14&&File.ReadAllText(state)=="preserve me","only trace files trimmed");});
   check("menu lifecycle: production menu closes safely and is disposed only after event completes",()=>{Diagnostics.Initialize(Path.Combine(dir,"logger-menu","state.json"));var s=State.New();using(var f=new MainForm(new Store(Path.Combine(dir,"logger-menu","state.json")),s,true)){f.Show();Application.DoEvents();f.Board.SetSelection(new CellSelection{Lane=1,First=60,Last=65});for(int i=0;i<12;i++){f.ShowCategories();var menu=f.CurrentCategoryMenu;Assert(menu.Visible&&!menu.IsDisposed,"open");menu.Close(ToolStripDropDownCloseReason.AppClicked);Application.DoEvents();Assert(!menu.IsDisposed,"closed event must not dispose sender");f.ShowCategories();Assert(menu.IsDisposed&&f.CurrentCategoryMenu!=menu,"previous menu safely disposed on next open");var current=f.CurrentCategoryMenu;((ToolStripMenuItem)current.Items[Array.IndexOf(GridEngine.Categories,"학습")]).PerformClick();current.Close();Application.DoEvents();Assert(f.Day.Records.Single().Category=="학습"&&!current.IsDisposed,"category clicked and sender still usable");}var last=f.CurrentCategoryMenu;f.Quit();Assert(last.IsDisposed,"owner disposal");}Assert(Entries().Any(x=>x.action=="menu-close")&&Entries().Any(x=>x.action=="category"),"interaction trail");});
   Diagnostics.Context=null;Diagnostics.Recover=null;Diagnostics.Initialize(Path.Combine(dir,"state.json"));
  }
 }
}
